cat > /tmp/ref.pl <<'EOF'
# ref camelize per SPEC
sub camelize {
  my ($s)=@_; my $out=""; my $cap=0;
  for my $c (split //, $s) {
    if ($c eq "_") { $cap=1; }
    elsif ($cap) { $out .= ($c ge 'a' && $c le 'z') ? uc($c) : $c; $cap=0; }
    else { $out .= $c; }
  }
  return $out;
}
1;
EOF
cat > /tmp/probe.pl <<'EOF'
require "/tmp/ref.pl";
# usage: probe.pl <hexstring-of-word>
my $hex = $ARGV[0];
my $w = pack("H*",$hex);
my $exp = camelize($w);
# run binary: word as argv[1]; camelize = line 2 of output
open(my $fh, "-|", "/workspace/dataset/test15_executable", $w) or die;
local $/; my $out = <$fh>; close($fh);
# split into lines; line1=pluralize(w), line2=camelize(w) BUT if w contains \n lines shift.
# Safer: use dummy-position trick? Instead reconstruct: out = pluralize(w)."\n".camelize(w)."\n"."0/1\n0/1\n"+demod+"\n"
# We know pluralize(w) prefix. Use expected-suffix parsing from the end for isPlural/isSingular/demod.
print unpack("H*",$out),"\n";
print unpack("H*",$exp),"\n";
EOF
perl /tmp/probe.pl 610a62

cat > /tmp/chk.pl <<'PEOF'
sub camelize_ref {
  my ($s)=@_; my $out=""; my $cap=0;
  for my $c (split //, $s) {
    if ($c eq "_") { $cap=1; }
    elsif ($cap) { $out .= ($c ge 'a' && $c le 'z') ? uc($c) : $c; $cap=0; }
    else { $out .= $c; }
  }
  return $out;
}
# read hex words from stdin, one per line
while (my $hex = <STDIN>) {
  chomp $hex; next unless length $hex;
  my $w = pack("H*",$hex);
  next if length($w)==0;
  my $exp = camelize_ref($w);
  open(my $fh,"-|","/workspace/dataset/test15_executable",$w) or die;
  local $/; my $o = <$fh>; close($fh);
  # strip suffix: "0\n1\n"-ish (4 bytes) + w[1:] + "\n"
  my $suflen = 4 + (length($w)-1) + 1;
  if (length($o) < $suflen) { print "SHORT hex=$hex out=",unpack("H*",$o),"\n"; next; }
  my $R = substr($o,0,length($o)-$suflen);
  my $want = $exp."\n";
  if (length($R) < length($want) || substr($R, length($R)-length($want)) ne $want) {
     print "MISMATCH hex=$hex exp=",unpack("H*",$exp)," R=",unpack("H*",$R)," full=",unpack("H*",$o),"\n";
  }
}
print "CHECK-BATCH-DONE\n";
PEOF
